// Request bodies of the payment endpoints.
import { z } from "zod";
import { PAYMENT_METHODS } from "../connectors/index.ts";

export const paymentMethodInput = z.enum(PAYMENT_METHODS);

export const createPaymentInput = z.object({
  invoiceId: z.string(),
  method: paymentMethodInput,
  amountMinor: z.number().int().positive(),
  /** Generated by the client per attempt, reused on retries after a network failure. */
  idempotencyKey: z.string().min(16).max(80),
});
export type CreatePaymentInput = z.infer<typeof createPaymentInput>;

export const refundPaymentInput = z.object({
  amountMinor: z.number().int().positive(),
  reason: z.string().min(3).max(200),
});
export type RefundPaymentInput = z.infer<typeof refundPaymentInput>;

/** Demo only: outcome of a simulated payment chosen by a signed-in user. */
export const simulatePaymentInput = z.object({
  outcome: z.enum(["success", "failure", "lost_notification", "duplicate", "wrong_amount"]),
});

/** Demo only: outcome chosen on the public payment page. */
export const simulatePublicPaymentInput = z.object({ outcome: z.enum(["success", "failure"]) });
